// priority: -27524
// -----------------------------------------------------------------------------------------------
// What cannot be obtained yet, or ever, stays out of the recipe viewer (tools/analysis obtainability audit, 2026-10-24).
//
// kubejs/data/grindless/tables/hidden_until.json, generated by the audit (node tools/analysis/reachability.mjs --pass obtain --dump <dump>
// --table <file>), lists every item and fluid of the GT mods that no source of the pack gives today, grouped by material:
//   until <era>   class B: it comes with that era of docs/journey.md, the era that reaches its place (orbit and fusion LuV, the space
//                 elevator ZPM, Proxima b UHV...). Hidden while the era is above IMPLEMENTED_ERA; its recipes stay on the server.
//                 What the pack already reaches (the Moon at the end of HV: titanium, helium-3; Mars at the end of EV: tungsten,
//                 samarium, merrillite; IV's uranium from the End's pitchblende, Venus's naquadah and Mercury's iridosmine) is not in the
//                 table.
//   until never   class C: junk (unused GTM and addon materials, leftovers of the addon machines the pack removed). Hidden for good, and
//                 its removeRecipes (recipes that only exist for it: an ingredient that only takes junk, or junk as every output) are
//                 removed. Nothing is unregistered: old saves keep every id.
// When an era lands, bump IMPLEMENTED_ERA: its content shows again (and add its places to tools/analysis/tiers/obtain.json, then rerun
// the audit with --table: what is still out moves to a later era).
// A group with `unless` names a switch of global.grindless.stations.switches (startup_scripts/grindless/lib/stations.js, from
// tables/stations.json): while that switch is on the group shows (the tether spool in the tether mode). An unknown switch keeps it hidden.
//
// Hiding = two tags, items and fluids. c:hidden_from_recipe_viewers: EMI 1.1.22 drops the tagged stacks from its index (and the pack's
// other scripts use it for the addon machines they remove and for the old items of earlier versions). grindless:hidden_with_recipes:
// assets/emi/index/stacks/grindless_hidden_with_recipes.json disables it in EMI ("disable"; EMI only reads its data files in the emi
// namespace), so EMI also drops every recipe with one of them as input, output or catalyst. Groups with keepRecipes (old items that
// convert into the new ones) only get the first tag: their conversion stays visible. JEI runs under EMI (EMI's JEMI plugin is JEI's
// runtime): there is no JEI list to hide from.
//
// Priority -100: the recipe handler runs after the scripts that add recipes (the ore plant generates plant recipes for junk ores too;
// KubeJS keeps added recipes apart from the datapack ones, so they are dropped from event.addedRecipes).
//
// Published for the smoke test (tools/test/overlay/kubejs/server_scripts/gg_test_hidden.js) and the recipe dump (info.json):
//   global.grindless.hidden = { implementedEra, eras, groups, hidden: { groups, items, fluids, keep }, shownBySwitch, isHidden(id), removed: {...} }
//
// Rhino: var + function inside every callback that runs more than once (this Rhino throws "redeclaration of var").
(function () {
  const G = global.grindless || (global.grindless = {})
  const IMPLEMENTED_ERA = 'uhv'
  const TABLE = 'kubejs/data/grindless/tables/hidden_until.json'
  const TAG = 'c:hidden_from_recipe_viewers'
  const RECIPES_TAG = 'grindless:hidden_with_recipes'
  const LOG = '[grindless/hidden] '
  const ERAS = ['steam', 'lv', 'mv', 'hv', 'ev', 'iv', 'luv', 'zpm', 'uv', 'uhv', 'uev', 'uiv', 'uxv', 'opv', 'max']

  var H = (G.hidden = {
    implementedEra: IMPLEMENTED_ERA,
    eras: ERAS,
    groups: [],
    hidden: { groups: 0, items: [], fluids: [], keep: [] },
    shownBySwitch: [],
    removeRecipes: [],
    removed: { listed: 0, original: 0, added: 0, missing: 0, ms: 0 },
    tagged: { items: 0, fluids: 0, missing: [] }
  })
  var hiddenSet = {}
  var keepSet = {}
  H.isHidden = function (id) {
    return hiddenSet[String(id)] === true
  }

  function rank(until) {
    return until === 'never' ? ERAS.length : ERAS.indexOf(until)
  }

  function load() {
    var table = null
    try {
      table = typeof G.readJsonTable === 'function' ? G.readJsonTable(TABLE) : JSON.parse(JsonIO.toPrettyString(JsonIO.readJson(TABLE)))
    } catch (e) {
      console.error(LOG + 'cannot read ' + TABLE + ': ' + e)
      return
    }
    if (ERAS.indexOf(IMPLEMENTED_ERA) < 0) {
      console.error(LOG + 'IMPLEMENTED_ERA ' + IMPLEMENTED_ERA + ' is not an era (' + ERAS.join(', ') + '): nothing is hidden')
      return
    }
    var limit = rank(IMPLEMENTED_ERA)
    var groups = table && table.groups ? table.groups : []
    var bad = []
    var items = []
    var fluids = []
    var keep = []
    var remove = []
    var shown = []
    var switches = G.stations && G.stations.switches ? G.stations.switches : null
    var count = 0
    groups.forEach(function (g) {
      var r = rank(g.until)
      if (r < 0) {
        bad.push(g.material + ' (' + g.until + ')')
        return
      }
      if (r <= limit) return
      if (typeof g.unless === 'string') {
        if (switches === null || !Object.prototype.hasOwnProperty.call(switches, g.unless)) {
          console.error(LOG + g.material + ': unless names an unknown switch "' + g.unless + '" (global.grindless.stations.switches: ' +
            (switches === null ? 'missing' : Object.keys(switches).join(', ')) + '): it stays hidden')
        } else if (switches[g.unless] === true) {
          shown.push(g.material)
          return
        }
      }
      count++
      ;(g.items || []).forEach(function (id) {
        items.push(id)
        hiddenSet[id] = true
        if (g.keepRecipes === true) keepSet[id] = true
      })
      ;(g.fluids || []).forEach(function (id) {
        fluids.push(id)
        hiddenSet[id] = true
        if (g.keepRecipes === true) keepSet[id] = true
      })
      if (g.keepRecipes === true) keep.push(g.material)
      if (g.until === 'never') (g.removeRecipes || []).forEach(function (id) { remove.push(id) })
    })
    if (bad.length > 0) console.error(LOG + 'groups with an unknown era in ' + TABLE + ': ' + bad.join(', '))
    H.groups = groups
    H.hidden = { groups: count, items: items, fluids: fluids, keep: keep }
    H.removeRecipes = remove
    H.shownBySwitch = shown
    console.info(LOG + 'implemented up to ' + IMPLEMENTED_ERA + ': hiding ' + count + ' of ' + groups.length + ' groups (' + items.length +
      ' items, ' + fluids.length + ' fluids; ' + keep.length + ' keep their recipes in view); ' + remove.length + ' junk recipes to remove' +
      (shown.length > 0 ? '; shown by a stations switch: ' + shown.join(', ') : ''))
  }

  load()

  // both tags for everything hidden, except the keepRecipes groups: only the index tag
  function tagAll(event, ids, exists, kind) {
    var ok = []
    var missing = []
    ids.forEach(function (id) {
      if (exists(id)) ok.push(id)
      else missing.push(id)
    })
    var withRecipes = ok.filter(function (id) { return keepSet[id] !== true })
    if (ok.length > 0) event.add(TAG, ok)
    if (withRecipes.length > 0) event.add(RECIPES_TAG, withRecipes)
    H.tagged[kind] = ok.length
    H.tagged.missing = H.tagged.missing.concat(missing)
    if (missing.length > 0) console.info(LOG + missing.length + ' hidden ' + kind + ' are not registered (skipped): ' + missing.slice(0, 10).join(', '))
  }

  ServerEvents.tags('item', function (event) {
    tagAll(event, H.hidden.items, function (id) { return Item.exists(id) }, 'items')
  })

  ServerEvents.tags('fluid', function (event) {
    tagAll(event, H.hidden.fluids, function (id) { return Fluid.exists(id) }, 'fluids')
  })

  ServerEvents.recipes(function (event) {
    var started = Date.now()
    var ids = H.removeRecipes
    if (ids.length === 0) return
    var want = {}
    ids.forEach(function (id) { want[id] = true })
    // datapack recipes: one direct lookup per id (KubeJS's id filter), first counted, then removed
    var filters = ids.map(function (id) { return { id: id } })
    var original = Number(event.findRecipeIds(filters).size())
    event.remove(filters)
    // recipes added by the pack's own scripts (the ore plant): KubeJS keeps them in event.addedRecipes, out of reach of remove()
    var added = 0
    var it = event.addedRecipes.iterator()
    while (it.hasNext()) {
      var r = it.next()
      var id = null
      try {
        id = String(r.getOrCreateId())
      } catch (e) {
        id = null
      }
      if (id !== null && want[id] === true) {
        it.remove()
        added++
      }
    }
    H.removed = { listed: ids.length, original: original, added: added, missing: ids.length - original - added, ms: Date.now() - started }
    console.info(LOG + 'removed ' + (original + added) + ' junk recipes (' + original + ' from datapacks, ' + added + ' added by scripts; ' +
      H.removed.missing + ' listed ids no longer exist) in ' + H.removed.ms + ' ms')
  })
})()
